import importlib.util
import json
import sys
from pathlib import Path

repo = Path('/testbed').resolve()
test_file = repo / 'qa_instances_eval/pybamm_qa/quick_plot_init_call_coverage_suite/files/tests/qa/quick_plot_init_call_coverage_suite_test.py'

spec = importlib.util.spec_from_file_location('qa_quick_plot_suite', str(test_file))
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

obj = mod.TestQuickPlotInitCallCoverageQA()

prefixes = (
    'pybamm.plotting.quick_plot.',
    'pybamm.solvers.processed_variable.',
    'pybamm.solvers.base_processed_variable.',
    'pybamm.solvers.solution.',
    'pybamm.expression_tree.',
)

covered = set()
repo_str = repo.as_posix() + '/'
capture_level = 0

def profiler(frame, event, arg):
    global capture_level
    module = frame.f_globals.get('__name__', '')
    qual = frame.f_code.co_qualname
    trace_name = f"{module}.{qual}"

    is_target = module == 'pybamm.plotting.quick_plot' and qual == 'QuickPlot.__init__'

    if event == 'call':
        if capture_level > 0 or is_target:
            filename = Path(frame.f_code.co_filename).resolve().as_posix()
            if filename.startswith(repo_str):
                rel = filename[len(repo_str):]
                if rel.startswith('src/pybamm') and not rel.startswith('src/pybamm/tests'):
                    if '<' not in qual and '>' not in qual and trace_name.startswith(prefixes):
                        covered.add((rel, trace_name))
        if capture_level > 0:
            capture_level += 1
        elif is_target:
            capture_level = 1

    elif event in ('return', 'exception'):
        if capture_level > 0:
            capture_level -= 1

    return profiler

sys.setprofile(profiler)
try:
    for i in range(1, 11):
        getattr(obj, f'test_case_{i:02d}')()
finally:
    sys.setprofile(None)

result = {
    'covered_functions': [
        {'file': f, 'func': fn}
        for f, fn in sorted(covered, key=lambda x: (x[0], x[1]))
    ]
}

out = Path('/tmp/quick_plot_covered.json')
out.write_text(json.dumps(result, indent=2))
print(f'wrote {out} with {len(result["covered_functions"])} entries')
PY

